/**
 * Package entry point.
 *
 * The implementation lives in `dist` and is fully regenerated by `pnpm build`
 * (debug) or `pnpm build:release` (production), so the published package always
 * ships the native addon, the JavaScript layer and the type declarations.
 */
export * from './dist/index.js';
export { default } from './dist/index.js';
